import csv,json,sys
def parse_rows(path):
 with open(path,newline="",encoding="utf-8") as f: return list(csv.DictReader(f))
def summarize(rows):
 out={}
 for r in rows:
  k=r["sku"]; out[k]=round(out.get(k,0)+int(r["quantity"])*float(r["unit_price"]),2)
 return out
if __name__=="__main__": print(json.dumps(summarize(parse_rows(sys.argv[1])),sort_keys=True))
